use crate::wasi::clocks::wall_clock;

struct Node;

/// Howard Hinnant's days-from-civil, inverted: civil date from days since the
/// Unix epoch (1970-01-01). Valid across the whole range we can get from a u64
/// seconds count.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = (z - era * 146_097) as i64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32; // [1, 12]
    (if m <= 2 { y + 1 } else { y }, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // The one capability this node holds: read the wall clock.
        let now = wall_clock::now();
        let seconds = now.seconds;

        let days = (seconds / 86_400) as i64;
        let (year, month, day) = civil_from_days(days);

        // ensures len(date) == 10: "YYYY-MM-DD". {:04} keeps the year four
        // digits for the realistic clock range, giving exactly ten characters.
        let date = format!("{:04}-{:02}-{:02}", year, month, day);

        // ensures started >= 0: started is u64, so this holds by construction.
        RunInfo {
            date,
            started: seconds,
        }
    }
}

export!(Node);
